import type { ChatDensity, ChatMessageProps, ChatRole, ChatState, ChatTone } from "../contracts";

export type ChatMessageContext = {
  from: ChatRole;
  state: ChatState;
  density: ChatDensity;
  tone: ChatTone;
  isUser: boolean;
  isAssistant: boolean;
  isSystem: boolean;
  isTool: boolean;
  isCompact: boolean;
  isStreaming: boolean;
  isError: boolean;
};

function getChatMessageContext({
  from,
  state,
  density,
  tone,
}: Required<Pick<ChatMessageProps, "from" | "state" | "density" | "tone">>): ChatMessageContext {
  return {
    from,
    state,
    density,
    tone,
    isUser: from === "user",
    isAssistant: from === "assistant",
    isSystem: from === "system",
    isTool: from === "tool",
    isCompact: density === "compact",
    isStreaming: state === "streaming",
    isError: state === "error",
  };
}

export function useChatMessage({
  from,
  state = "idle",
  density = "comfortable",
  tone = "neutral",
}: Pick<ChatMessageProps, "from" | "state" | "density" | "tone">) {
  return getChatMessageContext({ from, state, density, tone });
}

"use client";

import type { ComponentProps, CSSProperties } from "react";
import { createContext, useContext } from "react";

import type { ChatMessageProps } from "@/components/control-ui/contracts";
import { useChatMessage } from "@/components/control-ui/hooks/use-chat-message";
import type { ChatMessageKnobStyle } from "@/components/control-ui/knob-contracts";
import { cn } from "@/components/control-ui/lib/cn";

type ChatMessageContextValue = ReturnType<typeof useChatMessage>;

const ChatMessageContext = createContext<ChatMessageContextValue | null>(null);

function useChatMessageContext() {
  const context = useContext(ChatMessageContext);
  if (!context) throw new Error("ChatMessage compound components must be rendered inside <ChatMessage>.");
  return context;
}

export function ChatMessage({
  from,
  state = "idle",
  density = "comfortable",
  tone = "neutral",
  className,
  children,
  ...props
}: ChatMessageProps) {
  const message = useChatMessage({ from, state, density, tone });

  return (
    <ChatMessageContext.Provider value={message}>
      <article
        data-control-ui="chat-message"
        data-control-family="chat-message"
        data-slot="root"
        data-role={from}
        data-state={state}
        data-density={density}
        data-tone={tone}
        className={cn("w-full", className)}
        {...props}
      >
        {children}
      </article>
    </ChatMessageContext.Provider>
  );
}

export type ChatMessageRowProps = ComponentProps<"div"> & { style?: CSSProperties & ChatMessageKnobStyle };

export function ChatMessageRow({ className, children, ...props }: ChatMessageRowProps) {
  const message = useChatMessageContext();

  return (
    <div
      data-control-ui="chat-message"
      data-control-family="chat-message"
      data-slot="row"
      className={cn(
        "group flex w-full gap-2",
        message.isUser ? "justify-end" : "justify-start",
        message.isCompact ? "py-1" : "py-2",
        className,
      )}
      {...props}
    >
      {children}
    </div>
  );
}

export type ChatMessageAvatarProps = Omit<ComponentProps<"div">, "style"> & {
  style?: CSSProperties & ChatMessageKnobStyle;
};

export function ChatMessageAvatar({ className, ...props }: ChatMessageAvatarProps) {
  return (
    <div
      data-control-ui="chat-message"
      data-control-family="chat-message"
      data-slot="avatar"
      className={cn("mt-0.5 flex size-6 shrink-0 items-center justify-center", className)}
      {...props}
    />
  );
}

export type ChatMessageBodyProps = ComponentProps<"div"> & { style?: CSSProperties & ChatMessageKnobStyle };

export function ChatMessageBody({ className, ...props }: ChatMessageBodyProps) {
  const message = useChatMessageContext();

  return (
    <div
      data-control-ui="chat-message"
      data-control-family="chat-message"
      data-slot="body"
      className={cn("min-w-0", message.isUser ? "max-w-[76%]" : "max-w-[80%] flex-1", className)}
      {...props}
    />
  );
}

export type ChatMessageHeaderProps = Omit<ComponentProps<"div">, "style"> & {
  style?: CSSProperties & ChatMessageKnobStyle;
};

export function ChatMessageHeader({ className, ...props }: ChatMessageHeaderProps) {
  return (
    <div
      data-control-ui="chat-message"
      data-control-family="chat-message"
      data-slot="header"
      className={cn("mb-1 flex items-center gap-2 px-1", className)}
      {...props}
    />
  );
}

export type ChatMessageContentProps = Omit<ComponentProps<"div">, "style"> & {
  style?: CSSProperties & ChatMessageKnobStyle;
};

export function ChatMessageContent({ className, ...props }: ChatMessageContentProps) {
  const message = useChatMessageContext();

  return (
    <div
      data-control-ui="chat-message"
      data-control-family="chat-message"
      data-slot="content"
      data-role={message.from}
      data-streaming={message.isStreaming ? "" : undefined}
      className={cn(message.isUser && "px-[var(--padding-x)] py-[var(--padding-y)]", className)}
      {...props}
    />
  );
}

export type ChatMessageActionsProps = Omit<ComponentProps<"div">, "style"> & {
  style?: CSSProperties & ChatMessageKnobStyle;
};

export function ChatMessageActions({ className, ...props }: ChatMessageActionsProps) {
  return (
    <div
      data-control-ui="chat-message"
      data-control-family="chat-message"
      data-slot="actions"
      className={cn("mt-1 flex items-center gap-1", className)}
      {...props}
    />
  );
}

@layer components {
  :where([data-control-family="chat-message"][data-slot="root"]) {
    --chat-message-avatar-radius: 9999px;
    --chat-message-avatar-background: var(--card);
    --chat-message-avatar-border-color: var(--border);
    --chat-message-avatar-border-width: 1px;
    --chat-message-radius: 0px;
    --chat-message-corner-radius: 0px;
    --chat-message-background: transparent;
    --chat-message-background-image: none;
    --chat-message-foreground: var(--foreground);
    --chat-message-border-color: transparent;
    --chat-message-border-width: 0px;
    --chat-message-shadow: none;
  }
  :where([data-control-family="chat-message"][data-slot="avatar"]) {
    border: var(--chat-message-avatar-border-width) solid var(--chat-message-avatar-border-color);
    border-radius: var(--chat-message-avatar-radius);
    background: var(--chat-message-avatar-background);
    color: var(--muted-foreground);
  }

  :where([data-control-family="chat-message"][data-slot="content"]) {
    border: var(--chat-message-border-width) solid var(--chat-message-border-color);
    border-radius: var(--chat-message-radius);
    border-start-end-radius: var(--chat-message-corner-radius);
    background-color: var(--chat-message-background);
    background-image: var(--chat-message-background-image);
    box-shadow: var(--chat-message-shadow);
    color: var(--chat-message-foreground);
  }

  :where([data-control-family="chat-message"][data-slot="root"][data-role="user"]) {
    --chat-message-radius: var(--radius-field);
    --chat-message-corner-radius: var(--radius-lg);
    --chat-message-background: var(--primary);
    --chat-message-foreground: var(--primary-foreground);
    --chat-message-shadow: var(--shadow-sm);
  }

  :where([data-control-family="chat-message"][data-slot="content"][data-role="assistant"][data-streaming]) {
    @apply shimmer-text;
  }

  :where([data-control-family="chat-message"][data-slot="actions"]) {
    --_chat-message-actions-opacity: 0%;
    opacity: var(--_chat-message-actions-opacity);
    --_chat-message-actions-transition-property: opacity;
    transition-property: var(--_chat-message-actions-transition-property);
    transition-timing-function: var(--ease-standard);
    transition-duration: var(--duration-fast);
  }

  @media (hover: hover) {
    :where([data-control-family="chat-message"][data-slot="actions"]:is(:where(.group):hover *)) {
      --_chat-message-actions-opacity: 100%;
      opacity: var(--_chat-message-actions-opacity);
    }
  }

  :where([data-control-family="chat-message"][data-slot="content"]) {
    font-size: var(--text-body);
    line-height: calc(var(--spacing) * 5);
  }

  :where([data-control-family="chat-message"][data-slot="header"]) {
    font-size: var(--text-caption);
    color: var(--muted-foreground);
  }

  :where([data-control-family="chat-message"][data-slot="avatar"]) {
    font-size: var(--text-caption);
  }
}

